const payload = $input.first().json.body ?? $input.first().json;
const recipients = payload.recipients?.email ?? [];
const santri = payload.santri ?? {};
const orangTua = payload.orang_tua ?? {};
const alamat = payload.alamat ?? {};
const group = payload.group ?? {};
const ringkasan = payload.ringkasan?.baris ?? {};
const dokumen = payload.dokumen ?? {};
const event = payload.event ?? 'pendataan_baru';

function esc(value) {
  return String(value ?? '-').replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
}

function isRevisionNeeded() {
  return event === 'revisi_dokumen_diminta'
    || santri.perlu_revisi === true
    || dokumen.perlu_revisi === true
    || santri.status_pendaftaran === 'Ditolak'
    || santri.status_verifikasi === 'Ditolak';
}

const isStatusUpdate = event === 'status_verifikasi_diperbarui';
const isRevisionRequest = event === 'revisi_dokumen_diminta';
const needsRevision = isRevisionNeeded();
const title = isRevisionRequest
  ? 'Revisi Data/Berkas SPSB Diperlukan'
  : (isStatusUpdate ? 'Update Status Verifikasi Data SPSB' : 'Pendataan SPSB Berhasil Diterima');
const subject = isRevisionRequest
  ? `Revisi Data/Berkas SPSB - ${santri.nama_lengkap ?? ''}`
  : (isStatusUpdate
    ? `Update Status Verifikasi Data SPSB - ${santri.nama_lengkap ?? ''}`
    : `Ringkasan Pendataan SPSB - ${santri.nama_lengkap ?? ''}`);

const summaryRows = Object.entries(ringkasan)
  .map(([label, value]) => `<tr><td style="padding:7px 10px;border:1px solid #e5e7eb;font-weight:700;background:#f8fafc;">${esc(label)}</td><td style="padding:7px 10px;border:1px solid #e5e7eb;">${esc(value)}</td></tr>`)
  .join('');

const statusBlock = (isStatusUpdate || isRevisionRequest)
  ? `<div style="background:${needsRevision ? '#fff7ed' : '#ecfdf5'};border:1px solid ${needsRevision ? '#fed7aa' : '#bbf7d0'};border-radius:12px;padding:14px;margin:16px 0;"><p style="margin:0 0 6px;font-weight:700;color:${needsRevision ? '#c2410c' : '#047857'};">Status terbaru: ${esc(santri.status_label)}</p><p style="margin:0;color:#334155;">${esc(santri.pesan_status)}</p>${dokumen.catatan ? `<p style="margin:10px 0 0;color:#334155;"><strong>Catatan panitia:</strong><br>${esc(dokumen.catatan)}</p>` : ''}</div>`
  : '';

const groupBlock = (!isStatusUpdate && !isRevisionRequest)
  ? `<p><strong>Informasi grup kelas:</strong><br>${esc(group.aturan)}</p><p>Link grup kelas: ${group.link ? `<a href="${esc(group.link)}">${esc(group.link)}</a>` : 'Belum tersedia. Admin akan mengirimkan link menyusul.'}</p>`
  : '';
const revisionBlock = needsRevision
  ? `<p><strong>Link revisi data/berkas:</strong><br>${payload.links?.revisi ? `<a href="${esc(payload.links.revisi)}">${esc(payload.links.revisi)}</a>` : 'Link revisi belum tersedia. Silakan hubungi admin.'}</p><p>Silakan unggah ulang hanya dokumen yang diminta oleh panitia.</p>`
  : '';
const actionLink = needsRevision ? payload.links?.revisi : (isStatusUpdate ? payload.links?.cek_status : payload.links?.cetak);
const actionText = needsRevision ? 'Buka link revisi' : (isStatusUpdate ? 'Cek status pendataan' : 'Cetak bukti pendataan');

const html = `
<div style="font-family:Arial,sans-serif;color:#0f172a;line-height:1.55;">
  <h2 style="margin:0 0 12px;color:#047857;">${title}</h2>
  <p>Assalamu'alaikum Bapak/Ibu,</p>
  <p>${isRevisionRequest ? 'Panitia meminta revisi data/berkas' : (isStatusUpdate ? 'Status verifikasi data' : 'Data pendataan')} ananda <strong>${esc(santri.nama_lengkap)}</strong> ${isRevisionRequest ? 'agar dapat ditinjau kembali.' : (isStatusUpdate ? 'telah diperbarui oleh panitia.' : 'telah masuk ke sistem SPSB.')}</p>
  ${statusBlock}
  <table style="border-collapse:collapse;width:100%;max-width:720px;margin:16px 0;font-size:14px;">
    ${summaryRows}
    <tr><td style="padding:7px 10px;border:1px solid #e5e7eb;font-weight:700;background:#f8fafc;">Nama Ayah</td><td style="padding:7px 10px;border:1px solid #e5e7eb;">${esc(orangTua.ayah?.nama)}</td></tr>
    <tr><td style="padding:7px 10px;border:1px solid #e5e7eb;font-weight:700;background:#f8fafc;">Nama Ibu</td><td style="padding:7px 10px;border:1px solid #e5e7eb;">${esc(orangTua.ibu?.nama)}</td></tr>
    ${alamat.alamat_lengkap ? `<tr><td style="padding:7px 10px;border:1px solid #e5e7eb;font-weight:700;background:#f8fafc;">Alamat</td><td style="padding:7px 10px;border:1px solid #e5e7eb;">${esc(alamat.alamat_lengkap)}, ${esc(alamat.kelurahan_desa)}, ${esc(alamat.kecamatan)}</td></tr>` : ''}
  </table>
  ${groupBlock}
  ${revisionBlock}
  ${actionLink ? `<p>${actionText}:<br><a href="${esc(actionLink)}">${esc(actionLink)}</a></p>` : ''}
  <p style="margin-top:20px;">Jazakumullah khairan,<br>Panitia SPSB</p>
</div>`;

return recipients.map((recipient) => ({
  json: {
    to_email: recipient.email,
    to_name: recipient.name,
    subject,
    html,
    event,
    payload
  }
}));
